import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        int n = Integer.parseInt(tokens.get(0)), m = Integer.parseInt(tokens.get(1)), q = Integer.parseInt(tokens.get(2));
        List<String> images = tokens.subList(3, 3 + n), favs = tokens.subList(3 + n, 3 + n + m);
        HashSet<String> marked = new HashSet<>(favs);
        int first = 0, second = 0; // cursors into favorites and the original list
        StringBuilder sb = new StringBuilder();
        for (int t = 0; t < q; t++) {
            if (t > 0) sb.append(' ');
            if (first < m) { sb.append(favs.get(first++)); continue; }
            while (second < n && marked.contains(images.get(second))) second++;
            if (second < n) sb.append(images.get(second++));
            else sb.append("NULL");
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	m, _ := strconv.Atoi(next())
	q, _ := strconv.Atoi(next())
	images := make([]string, n)
	for i := range images {
		images[i] = next()
	}
	favs := make([]string, m)
	marked := make(map[string]bool, m)
	for i := range favs {
		favs[i] = next()
		marked[favs[i]] = true
	}
	out := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer out.Flush()
	first, second := 0, 0 // cursors into favorites and the original list
	for t := 0; t < q; t++ {
		if t > 0 {
			out.WriteByte(' ')
		}
		if first < m {
			out.WriteString(favs[first])
			first++
			continue
		}
		for second < n && marked[images[second]] {
			second++
		}
		if second < n {
			out.WriteString(images[second])
			second++
		} else {
			out.WriteString("NULL")
		}
	}
	out.WriteByte('\n')
}
